export const Marquee = () => {
  const text = 'STUPID STUDIOS — CINEMATIC SHORTS — TAMIL ORIGINALS — ';
  return (
    <div className="relative py-8 border-y border-white/10 bg-[#0a0a0a] overflow-hidden">
      <div className="marquee-track">
        {[0, 1].map((k) => (
          <span
            key={k}
            className="font-display font-medium text-4xl md:text-6xl uppercase text-white/90 px-4"
          >
            {text.repeat(2).split('—').map((chunk, i) =>
              chunk.trim() ? (
                <span key={i}>
                  {chunk.trim()}
                  <span className="text-[#E11D48] mx-6">✦</span>
                </span>
              ) : null
            )}
          </span>
        ))}
      </div>
    </div>
  );
};
